<template>
  <div class="scope-editor">
    <el-alert title="分别确认未发取消与已发退回数量" description="填0的商品继续原履约，不通过退款金额推算数量。共用发货单撤回后，其他商品需求保留并等待重新分仓。" type="info" :closable="false" />
    <template v-if="executed"><el-alert title="已有执行记录，本次重审保留原货物范围" description="仅更新退款申请的审核依据；原任务、仓库及库存请求继续沿用，已执行数量和退回地址不在重审时改写。" type="warning" :closable="false" /><el-table :data="activeTasks" size="small"><el-table-column prop="order_line_id" label="原商品行" /><el-table-column prop="shipment_line_id" label="原发货来源" /><el-table-column label="原动作"><template slot-scope="s">{{ actionLabel(s.row.action) }}</template></el-table-column><el-table-column prop="quantity" label="原处理数量" /></el-table></template>
    <template v-else><div v-for="line in lines" :key="line.order_line_id" class="scope-line"><strong>{{ line.goods_name }} · {{ line.sku_sn }}</strong>
                       <div v-if="Number(line.unshipped_quantity) > 0" class="scope-input"><span>取消未发商品（最多 {{ line.unshipped_quantity }} {{ line.stock_unit }}）</span><el-input-number v-model="cancel[line.order_line_id]" :min="0" :max="Number(line.unshipped_quantity)" :precision="0" size="small" @change="emit" /></div>
                       <div v-for="source in shipped(line)" :key="source.shipment_line_id" class="scope-input"><span>{{ source.store_code }} · {{ source.shipment_sn }} · 已出库 {{ source.shipped_quantity }} {{ line.stock_unit }}</span><el-select v-model="actions[source.shipment_line_id]" size="small" @change="emit"><el-option label="协商退回" value="RETURN" /><el-option label="在途拦截后退回" value="INTERCEPT" /><el-option label="拒收退回" value="REFUSAL" /></el-select><el-input-number v-model="returns[source.shipment_line_id]" :min="0" :max="Number(source.shipped_quantity)" :precision="0" size="small" @change="emit" /></div>
                     </div>
      <template v-if="hasReturn"><el-form-item label="退回仓库" required><el-select v-model="store" filterable :loading="warehouseLoading" placeholder="选择本次退回接收仓" style="width:100%" @change="emit"><el-option v-for="warehouse in warehouses" :key="warehouse.code" :value="warehouse.code" :label="`${warehouse.name || warehouse.code}（${warehouse.code}）`" /></el-select><el-alert v-if="warehouseError" :title="warehouseError" type="warning" :closable="false" /><el-button v-if="warehouseError" type="text" @click="loadWarehouses">重新加载退回仓</el-button></el-form-item><el-form-item label="寄回地址" required><el-input v-model.trim="address" maxlength="500" @input="emit" /></el-form-item><el-form-item label="寄回联系信息" required><el-input v-model.trim="contact" maxlength="200" @input="emit" /></el-form-item></template></template>
  </div>
</template>
<script>
import { refundGoodsOptions } from '@/api/order/refund'
export default { name: 'RefundGoodsScopeEditor', props: { fulfillment: { type: Object, required: true }, existingTasks: { type: Array, default: () => [] }, refundId: { type: Number, default: 0 }}, data: () => ({ cancel: {}, returns: {}, actions: {}, store: '', address: '', contact: '', warehouses: [], warehouseError: '', warehouseLoading: false }), computed: { activeTasks() { return this.existingTasks.filter(task => task.state !== 'CANCELED') }, executed() { return this.activeTasks.some(task => task.state !== 'PENDING' || task.cutoff_id || task.return_plan_id) }, lines() { return this.fulfillment.lines || [] }, hasReturn() { return Object.values(this.returns).some(value => Number(value) > 0) } }, watch: { hasReturn(value) { if (value && !this.warehouses.length) this.loadWarehouses() } }, created() { if (this.executed) { this.$emit('input', this.activeTasks.map(task => ({ ...this.parsePlan(task.plan_input), action: task.action, order_line_id: task.order_line_id, shipment_line_id: task.shipment_line_id, quantity: task.quantity }))); return } this.lines.forEach(line => { this.$set(this.cancel, line.order_line_id, 0); this.shipped(line).forEach(source => { this.$set(this.returns, source.shipment_line_id, 0); this.$set(this.actions, source.shipment_line_id, 'RETURN') }) }) }, methods: { async loadWarehouses() { this.warehouseLoading = true; this.warehouseError = ''; try { this.warehouses = (await refundGoodsOptions(this.refundId)).data.warehouses || [] } catch (error) { this.warehouseError = error.message || '退回仓加载失败，请重试' } finally { this.warehouseLoading = false } }, parsePlan(value) { if (value && typeof value === 'object') return value; try { return JSON.parse(value || '{}') } catch (error) { return {} } }, actionLabel(action) { return { CANCEL: '取消未发', RETURN: '协商退回', INTERCEPT: '在途拦截', REFUSAL: '拒收退回' }[action] || action }, shipped(line) { return (line.sources || []).filter(source => Number(source.shipped_quantity) > 0) }, emit() { const tasks = []; this.lines.forEach(line => { const quantity = Number(this.cancel[line.order_line_id] || 0); if (quantity) tasks.push({ action: 'CANCEL', order_line_id: line.order_line_id, quantity }); this.shipped(line).forEach(source => { const quantity = Number(this.returns[source.shipment_line_id] || 0); if (quantity) tasks.push({ action: this.actions[source.shipment_line_id], order_line_id: line.order_line_id, shipment_line_id: source.shipment_line_id, quantity, store_code: this.store, return_address: this.address, return_contact: this.contact }) }) }); this.$emit('input', tasks) } }}
</script>
<style scoped>
.scope-line{margin:12px 0;padding:12px;border:1px solid #e4e7ed;border-radius:4px}.scope-input{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-top:12px}.scope-input>span{flex:1;min-width:180px}.scope-input .el-select{width:160px}
</style>
